quests[12287] = { id = 12287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orik Treuherz und der Vergessene Strand", description = "Ich habe in die Kugel gesehen und sah den Pfad, den Ihr gehen müsst, {name}.\n\nVor vielen Jahren wurde ein Gräuel an den Küsten der Drachenöde begangen. Die Tat selbst verbleibt im Dunkel, doch ich bin sicher, dass Euer Schicksal im Süden liegt, inmitten der Ruinen des Vergessenen Strands.\n\nNehmt die Straße nach Südosten über den verwüsteten Dorfplatz. Folgt dem Pfad bis Ihr die Dämmerkuppe erreicht. Dort werdet Ihr einen meiner alten Freunde treffen, Orik Treuherz. Er wird Euch erwarten.", sourceObjective = "Sucht Orik Treuherz auf der Dämmerkuppe in der Drachenöde auf.", completion = "Zelig schickte Nachricht, mein Freund. Wir haben Euch erwartet.\n\nIch bin Orik Treuherz, Paladin des Argentumkreuzzugs. Die Priesterin auf der anderen Seite des Feuers ist Tilda Darathan. Wir sind im Namen der Argentumdämmerung hier, um die unglücklichen verdammten Seelen, die versuchen Wintergarde zu verlassen, zu bezwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12288] = { id = 12288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfordert!", description = "Ihr da, {class}! Helft mir!\n\nWertvolle Leben gehen verloren! Es gibt einfach viel zu viele Verwundete, als dass ich mich um sie alle alleine kümmern könnte. Wenn wir unsere Soldaten nicht heilen können, dann können wir gleich allesamt unsere sieben Sachen packen und aus den Grizzlyhügeln verschwinden!\n\nHier, nehmt diese Abschnürbinde und verbindet damit die unten auf dem Schlachtfeld liegenden Verwundeten.\n\nBeeilt Euch, {name}! Sie liegen im Sterben!!", sourceObjective = "Aumana beim Holzfällerposten Blauhimmel möchte, dass Ihr die erneuernde Abschnürbinde auf 10 verwundete Scharmützler anwendet.", completion = "Oh, ich danke Euch, ich danke Euch.\n\nDank Euch werden wir einen weiteren Tag erleben. Vielleicht gibt es noch Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12289] = { id = 12289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tritt rein, solang' sie am Boden liegen", description = "Dies ist ein schwarzer Tag für die Allianz. Viele gute Menschen sind tot oder liegen im Sterben. Unser einziger Trost ist, dass sie gut gekämpft und viele unserer Feinde mit in den Tod gerissen haben.\n\nDa der Großteil unserer Streitkräfte in der Venturebucht stationiert ist, müssen wir uns diesem Sturm alleine stellen. Die Ressourcen dieser Region sind für die Allianz essentiell und können das Zünglein an der Waage im Kampf gegen die Horde bedeuten. Wir dürfen nicht versagen!\n\nGeht nun, {name}. Schlagt zu, während sie noch ihre Wunden lecken. Nehmt Rache für Eure gefallenen Kameraden und seid das Licht unserer Hoffnung!", sourceObjective = "Unteroffizier Hartsmann möchte, dass Ihr 15 Einheiten oder Spieler der Horde im Holzfällerlager Blauhimmel besiegt.", completion = "Gut gemacht, {name}.\n\nIhr habt uns hier etwas Zeit verschafft, wenn auch wohl nicht mehr als einen Tag. Dennoch dankt Euch die Allianz für Euren Einsatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[12290] = { id = 12290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Düstergraselixier", description = "Die Geister der Verdammten spuken an der Küste umher. Zu Lebzeiten waren sie tapfere und ehrenhafte Soldaten der Allianz, doch im Tod sind sie verflucht. Wenn wir sie befreien wollen, müssen wir die Quelle ihrer Pein finden!\n\nIm Südosten, auf den Düsterhöhen werdet Ihr ein seltenes Kraut finden, das Düstergras genannt wird. Daraus werde ich ein Elixier zubereiten, welches Euch zeitlich begrenzten Zugang zur Welt der Vergessenen gewähren wird. Geht jetzt und sammelt das Gras.", sourceObjective = "Orik Treuherz auf der Dämmerkuppe in der Drachenöde möchte, dass Ihr 5 Düstergräser von den Düsterhöhen holt.", progress = "Habt ihr das Düstergras besorgt?", completion = "<Orik nimmt das Düstergras und beginnt, ein Elixier zu mixen.>\n\nEs dauert nicht mehr lange, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12291] = { id = 12291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vergessene Geschichte", description = "Die Toxine im Düstergraselixier werden Euch bewusstlos werden lassen. Die Wirkung des Düstergrases ist so stark, dass selbst Euer Geist getäuscht wird, wodurch Ihr für kurze Zeit in die Welt der Toten eintreten könnt.\n\nWenn Ihr dann ein Geist seid, müsst Ihr mit den geisterhaften Bewohnern des Vergessenen Strands reden. Findet die Quelle ihrer Pein und kehrt zu mir zurück.\n\nDenkt daran, {name}, diese Geister waren einst Soldaten der Allianz. behandelt sie mit Respekt, Ehre und Würde.\n\nNun nehmt das Elixier und wagt Euch nach Süden zur Vergessenen Küste.", sourceObjective = "Orik Treuherz auf der Dämmerkuppe in der Drachenöde möchte, dass Ihr Euch die Geschichte der vergessenen Arbeiter, vergessenen Scharfschützen, vergessenen Ritter und der vergessenen Fußsoldaten anhört.", progress = "Ich habe genug Düstergras, um noch mehr Elixiere herzustellen, {name}.", completion = "<Tränen sammeln sich in Oriks Augen.>\n\nSie wissen es nicht. Keiner von ihnen weiß es! Sie halten Arthas für einen großen Helden, wo es in Wirklichkeit doch Arthas war, der die Schiffe verbrennen lies. Es war Arthas der uns in dieser gefrorenen Öde dem Tod überließ!\n\n<Orik weint.>\n\nNicht alle Soldaten der Flotte des Prinzen sind im frostigen Winter umgekommen. Ich war nur ein Jüngling, als ich die Chance bekam, gegen die Geißel zu kämpfen... und unsere Heimat vor der sicheren Zerstörung zu retten. Ich ergriff diese Chance, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12292] = { id = 12292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unterstützung der Einheimischen", description = "Der Kampf mit der Horde ist in den Grizzlyhügeln zum Stillstand gekommen. Unsere Streitkräfte sind fast gleich stark und alle Zeichen deuten darauf hin, dass wir eine Pattsituation erreicht haben.\n\nBis zu diesem Morgen jedenfalls. Die einheimischen Fallensteller und Pelzjäger haben um unsere Hilfe gebeten. Anscheinend hat die Horde etwas, das ihnen gehört... Irgendein Relikt.\n\nWir holen es ihnen zurück und gewinnen dank ihrer Unterstützung den Vorsprung, den wir benötigen. Macht Euch auf zum Handelsposten Immergrün, westlich von Burg Siegeswall, und seht Euch nach einer Zedernholzkiste um.", sourceObjective = "Leutnant Dumont bei der Ammertannhütte möchte, dass Ihr Euch zum Handelsposten Immergrün begebt und die Zedernholzkiste beschafft.", progress = "Habt Ihr die Kiste für mich, {name}?", completion = "Sie ist verschlossen, oder? Sieht ziemlich gewöhnlich aus.\n\n<Leutnant Dumont schüttelt die Kiste, was ein hölzernes Klappern hervorruft.>\n\nIch denke, das macht nichts. Solange uns das hier einen Vorsprung gegenüber der Horde verschafft, ist es mir auch egal, wenn hier drin das Heilmittel gegen die Seuche wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[12293] = { id = 12293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schließt den Handel ab", description = "Wir haben, was die Fallensteller wollen. Nun ist es an uns, sie auf unsere Seite zu bringen.\n\nBringt die Kiste zu einem Fallensteller namens Ivan im Posten des Espenhains, gleich nördlich von hier.\n\nWenn alles gut geht, werden wir bald Waldmänner als Späher für die königliche Armee einsetzen können.", sourceObjective = "Bringt die Zedernholzkiste zu Ivan im Posten des Espenhains.", progress = "Habt Ihr etwas für uns?", completion = "Ihr habt es geschafft! Ihr habt die Kiste, welche die Horde uns gestohlen hat, zurückgebracht. Wir danken Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12294] = { id = 12294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein vorläufiger Pakt", description = "Nun gut, {name}. Euer Volk hat seinen Teil der Abmachung eingehalten.\n\nSagt Dumont, dass wir auch unseren Teil einhalten werden.", sourceObjective = "Kehrt zu Leutnant Dumont in der Ammertannhütte zurück.", completion = "Ausgezeichnete Arbeit, {name}. Mit der Hilfe der Einheimischen steht uns auch die logistische Unterstützung zur Verfügung, die wir dazu brauchen, um die Horde in dieser Region auszumanövrieren.\n\nIch habe noch mehr Aufgaben für Euch, falls Ihr daran interessiert seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[12295] = { id = 12295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Übung in Sachen Diplomatie", description = "Wir hatten wochenlang versucht, mit den Fallenstellern zu verhandeln, jedoch erfolglos, bis Ihr ihre verdammte Kiste gefunden habt.\n\nDas sollten gute Neuigkeiten für unseren Entsandten in Silberwasser sein. Vor ungefähr einer Woche haben wir Ducal dorthin geschickt und sein letzter Brief lässt darauf schließen, dass er nur wenig Fortschritt gemacht hat.\n\nGeht nach Silberwasser und helft ihm bei seinen diplomatischen Angelegenheiten. Folgt den Straßen in Richtung Norden. Nach ein paar Brücken solltet Ihr dort ankommen.", sourceObjective = "Sprecht mit dem Entsandten Ducal in Silberwasser.", completion = "Gut, Euch endlich kennenzulernen, {name}! Wir haben hier oben von Euch gehört. Willkommen in Silberwasser.\n\nDiese Fallensteller sind ein toller Haufen Jungs und Mädels. Ein hartes Völkchen - sie kennen sich sehr gut mit dem hiesigen Gelände aus. Ihr werdet sehen, dass es eine großartige Sache ist, dass wir sie endlich auf unsere Seite geholt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12296] = { id = 12296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leben oder Tod", description = "Oh, dieses Gemetzel...\n\nIch habe schon viele Schlachten erlebt, {class}, aber das war brutaler als alles, was ich bisher gesehen habe. Unser Kampf gegen die Horde ist erbarmungsloser denn je geworden. Es heißt hier in Nordend sie oder wir... Leben oder Tod.\n\nWenn wir hier auch nur einen Tag länger überleben wollen, müssen wir unsere Verletzten heilen. Es sind zu viele, als dass ich sie alleine retten könnte.\n\nIch habe besondere Verbände hergestellt, die es ermöglichen, dass Ihr mir helfen könnt. Nehmt sie und behandelt diejenigen damit, die ihren Wunden noch nicht erlegen sind.", sourceObjective = "Rheanna beim Holzfällerposten Blauhimmel möchte, dass Ihr die erneuernde Bandage bei 10 verwundeten Westfall-Einheiten anwendet.", completion = "Wundervoll!\n\nDie Allianz wird noch einen weiteren Tag erleben, nicht zuletzt dank Eures Fleißes.\n\nNehmt meinen Dank an, Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[12297] = { id = 12297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Verrätern und Verrat", description = "Die Liste, die ich in Händen halte, muss an Oberkommandant Halford Wyrmbann überbracht werden. Er kommandiert die 7. Legion, die in der Feste Wintergarde an der östlichen Grenze der Drachenöde stationiert ist.\n\nWenn sich irgendeiner der Verräter auf dieser Liste in Wintergarde befindet... könnten die Folgen katastrophal sein.\n\nBeeilt Euch, {name}. Zeigt Greer Erzhammer hier in Westwacht dieses Schreiben und erklärt ihm, was es mit Eurer Mission auf sich hat. Für die Reise nach Wintergarde wird er Euch seinen schnellsten Greifen geben!", sourceObjective = "Hauptmann Adams möchte, dass Ihr das Schreiben der Allianz zu Greer Erzhammer in Westwacht bringt.", progress = "Hallo, {class}.", completion = "<Greer schiebt seine Brille auf die Stirn, liest sich die Mitteilung durch und blickt Euch verwundert an.>\n\nIch werde Euch meinen schnellsten Greifen geben! Diese Information muss unverzüglich an Oberkommandant Wyrmbann ausgehändigt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12298] = { id = 12298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberkommandant Halford Wyrmbann", description = "<Greer gibt Euch das Schreiben wieder zurück.>\n\nHimmelsweise wird Euch nach Wintergarde bringen, {name}. Ich kann Euch versichern, dass dies der schnellste Flug sein wird, den Ihr je erlebt habt. Geht jetzt!", sourceObjective = "Überbringt Oberkommandant Halford Wyrmbann das Schreiben der Allianz. Er befindet sich in der Feste Wintergarde im Osten der Drachenöde.", progress = "Was habt Ihr denn da, Soldat?", completion = "<Der Oberkommandant liest sich das Schreiben durch und zerknüllt es anschließend.>\n\nWisst Ihr, wo sich diese Leute auf der Liste im Moment befinden? Seht Euch draußen in der Nähe des Eingangstores einmal um. Es sind diejenigen, die vom Torbogen baumeln.\n\nGhulköder...", sourceObjectiveStatus = "unverified-source-field" }
quests[12299] = { id = 12299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nördliche Gastfreundschaft", description = "Gut, Euch zu sehen. Lasst uns unseren Pakt zelebrieren, indem wir zünftig auf Hordejagd gehen.\n\nIhr findet außerhalb der Stadt im Westen einige Marodeure von Burg Siegeswall. Warum begebt Ihr Euch nicht dorthin und bringt sie wie räudige Tiere, die sie ja auch sind, zur Strecke?\n\nLasst uns doch mal sehen, ob unsere neuen Verbündeten ihren großen Worten auch Taten folgen lassen.", sourceObjective = "Sergei in Silberwasser will, dass Ihr 8 Marodeure von Burg Siegeswall tötet.", completion = "Nicht schlecht, nicht schlecht. Am Ende seid Ihr nicht ganz so weich wie manche der anderen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12300] = { id = 12300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eignungstest", description = "Gut, <Freund/Freundin>. Ihr habt uns einen oder zwei Gefallen erwiesen, aber das alleine zeugt nicht von Mut.\n\nIn dieser Gegend seid Ihr kein wahrer Jäger, solange Ihr nicht die Haut Eurer Beute tragt.\n\n<Sergei zieht sein Kürschnermesser aus der Scheide und reicht es Euch.>\n\nDer Anführer dieser mutterlosen Orcs, die unsere Stadt angreifen, wird Knochenknacker genannt; Ihr findet ihn in einem Lager weiter nordwestlich von hier.\n\nJa, richtig. Ihr werdet das Monster häuten.", sourceObjective = "Findet Unteroffizier Knochenknacker nordwestlich von Silberwasser und besteht den Eignungstest.", progress = "Die Einwohner Silberwassers... sind nicht das, was sie zu sein scheinen.", completion = "Tut es nicht, {name}. Die Leute, die Euch hierher sandten... Ihr dürft ihnen nicht trauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12301] = { id = 12301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Möge die Wahrheit uns befreien", description = "Zelig hat mir vor Jahren diese Kristallkugel mit speziellen Anweisungen zu ihrer Verwendung übergeben. Fünf Jahre lang - wann auch immer ich Wut, Angst oder Kummer bezüglich des hier Geschehenen verspürte - sollte ich meine Gedanken auf diese Kugel konzentrieren.\n\nJetzt verstehe ich, wieso Zelig mir diese Kugel gab.\n\nBringt meine kristalline Kugel zum Vergessenen Strand. Findet die Ruinen meiner alten Basis in den oberen Gefilden des Strands und legt die Kugel in die Mitte der Stadt. Lasst die Vergessenen die Welt mit meinem Herzen und meiner Seele sehen.", sourceObjective = "Orik Treuherz auf der Dämmerkuppe in der Drachenöde möchte, dass Ihr Oriks kristalline Kugel in den Ruinen des Vergessenen Strands einsetzt, um die Vergessenen zu erlösen.", completion = "<Orik wirft Euch ein Lächeln entgegen.>\n\nIhr habt heute eine gute Tat vollbracht, {name}. Hunderte verlorener Seelen wurden nun Dank Euch erlöst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12302] = { id = 12302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte der Warnung", description = "Danke, dass Ihr mir helft, {name}. Mein Name ist Sasha. Hört zu, ich muss so schnell wie möglich von hier verschwinden.\n\nDie Leute, die Euch hergeschickt haben… meine Leute… sie haben sich verändert. Sie sind keine guten Leute mehr… und wollen, dass Ihr Euch in... in einen von ihnen verwandelt.\n\nDieser... \"Test\", mit dem sie Euch beauftragt haben, ist nur der Anfang.\n\nBegebt Euch zum nordwestlichen Ende von Silberwasser. Dort werdet Ihr etwas Interessantes finden...\n\nViel Glück... und vertraut niemandem.", sourceObjective = "Begebt Euch zum nordwestlichen Ende von Silberwasser.", completion = "Wer ist da? Seid Ihr hier, um mich zu töten?\n\nBitte! Das müsst Ihr nicht tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[12303] = { id = 12303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kriegsanstrengungen finanzieren", description = "<Der Rüstmeister senkt seine Stimme und flüstert Euch zu.>\n\n{class}, ich brauche Eure Hilfe - unsere Truhen sind leer. Unsere gesamten Mittel sind an den Vorposten der Kor'kron und den Kampf an der Pforte des Zorns gegangen.\n\nMir wurde jedoch zugeflüstert, dass sich auf den Schiffswracks am Vergessenen Strand im Südosten Schätze ergattern lassen.\n\nWir müssen schon bald etwas unternehmen oder wir werden den Kampf gegen den Scharlachroten Ansturm nicht weiterführen können. Krieg ist nicht gerade billig, müsst Ihr wissen!", sourceObjective = "Quartiermeister Bartlett in Gallgrimm möchte, dass Ihr 6 vergessene Schätze beschafft.", progress = "Wie viel von den Allianzschätzen konntet Ihr in Eure Finger bekommen?", completion = "<Dem Rüstmeister stockt der Atem, worauf er Euch einen Moment lang skeptisch mustert.>\n\nIch vertraue einmal darauf, dass Ihr nichts von dem Gold für Euch selbst behalten habt? Ich denke nicht, dass Ihr angesichts dessen, dass hier das Schicksal von Gallgrimm auf dem Spiel steht, so selbstsüchtig sein könntet, oder?\n\nAußerdem werde ich Euch prozentual am Gewinn beteiligen. Es ist zwar nicht viel, doch in Zeiten wie diesen, muss ein jeder Opfer bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12304] = { id = 12304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Grundstück am Strand", description = "Es ist Zeit, dass Gallgrimm expandiert!\n\nWir werden uns um den Scharlachroten Ansturm schon rechtzeitig kümmern, doch zuerst möchte ich, dass Ihr dafür sorgt, dass unsere Anstrengungen am Vergessenen Strand zum Ziel führen. Die Grundstücke dort versprechen einiges, und habt Ihr schon die Aussicht gesehen?\n\nUnglücklicherweise ist der Ort nur so von Menschengeistern, gestrandeten Mannschaften und dergleichen verpestet. Sie wollen einfach nicht wahrhaben, dass sie tot sind.\n\nSäubert den Strand und die Gewässer vor der Küste und wir beide könnten vielleicht darüber reden, dort unten schon bald ein gemütliches, neues Mausoleum zu bauen.", sourceObjective = "Feldmesser Hansen gleich nördlich des Vergessenen Strands möchte, dass Ihr 20 vergessene Geister vernichtet.", completion = "Habt Ihr's jetzt vor Augen, {class}? Es wird DER Urlaubsort in Nordend schlechthin!\n\nWie gefällt Euch denn der Name \"Hansens Bucht\" oder vielleicht \"Bucht von {name}\"? Hat was, findet Ihr nicht auch?", sourceObjectiveStatus = "unverified-source-field" }
quests[12305] = { id = 12305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedanken des Abschieds", description = "Ihr habt mir und Hunderten von Veteranen der Allianz Ehre erwiesen, {name}. Es war weise von Zelig, Euch hierher zu schicken. Bitte geht zu ihm zurück und überbringt ihm meinen Dank. Er wird über das, was am Vergessenen Strand geschehen ist, erfreut sein.\n\nDie Gabe, in die Zukunft zu blicken, wurde mir zwar, im Gegensatz zu Zelig, nicht zu Teil. Dennoch bin ich sicher, dass Großes auf Euch wartet, <mein Freund/meine Liebe>.\n\nLebt wohl.", sourceObjective = "Kehrt zu Zelig dem Visionär in der Feste Wintergarde in der Drachenöde zurück.", completion = "<Zelig lächelt.>\n\nIch fühle mich Euch zu tiefster Dankbarkeit verpflichtet, mein Held. Orik ist für mich wie ein Bruder. Ihr habt sein Leben verändert und den Hoffnungen zahlloser anderer neues Leben eingehaucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12306] = { id = 12306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bier des Monats e.V.", description = "Gemeinsam ist man stark, {name}. Ein Mitglied des \"Bier des Monats e.V.\" hat immer das beste Bier zur Hand.\n\nBringt noch heute Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in Orgrimmar.", sourceObjective = "Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in Orgrimmar.", progress = "Habt Ihr Euren Antrag ausgefüllt?", completion = "Du wirst dich uns anschließen, {name}? Wir sind gut zu dir, Mann. Wenn du bei diesem Verein mitmachst, bekommst du nur das Beste!\n\nZu Monatsbeginn schicken wir dir Bier. Wenn's dir schmeckt, dann komm doch wieder hierher. Wir sorgen dafür, dass du noch mehr davon bekommst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12307] = { id = 12307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsbannwurzel", description = "Habt Ihr schon von der Wolfsbannpflanze gehört? Es ist ein schreckliches Unkraut... es zerstört unsere Ernte.\n\nWir haben die ganze letzte Woche damit verbracht, es zu beseitigen, doch die Wurzeln fangen wieder an zu sprießen.\n\nEs mag vielleicht nicht dringend erscheinen, doch ein Wiederaufleben der Pflanze könnte eine wahre... Katastrophe sein. Denkt Ihr, dass Ihr uns dabei helfen könntet, die Wurzeln in der Nähe des Dorfes herauszureißen?", sourceObjective = "Katja in Silberwasser möchte, dass Ihr 8 Wolfsbannwurzeln ausreißt.", completion = "<Katja schwankt und wendet sich nervös von Euch ab.>\n\nIch danke Euch, {name}. Ihr seid nicht mit Wolfsbann in Berührung gekommen, oder? Ich hab' diese... Allergien, die mir hin und wieder Probleme bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12308] = { id = 12308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus Silberwasser", description = "Ihr... Ihr seid keiner von ihnen? Schnell! Lasst mich raus!\n\nWir müssen schleunigst zur Ammertannhütte! Wenn Leutnant Dumont erst einmal herausfindet, wer diese Leute wirklich sind, dann wird diese Stadt in Schutt und Asche gelegt werden!", sourceObjective = "Öffnet den hölzernen Käfig und helft dem befreiten Späher der Allianz, aus Silberwasser zu entkommen. Meldet Euch bei Leutnant Dumont, sobald Ihr die Ammertannhütte erreicht habt.", completion = "Worgen. Verdammte, vom Licht verlassene, dreckige Worgen.\n\nEs ist an der Zeit, dass wir den Einheimischen zeigen, was zivilisierte Leute mit Bestien, wie sie es sind, machen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12309] = { id = 12309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Durkon!", description = "Nachdem die Geißel an der Südmauer durchgebrochen war, habe ich Dragoner Durkon befohlen, die örtliche Gruft zu untersuchen. Vor wenigen Augenblicken habe ich seinen Bericht erhalten.\n\nDie Untoten, die uns heimsuchen, kommen aus zwei Quellen: den Ruinen von Wintergarde, die nun eine Brutstätte der Geißel sind, und aus unserer eigenen Gruft! In all dem Chaos und der Verwirrung hat es die Geißel geschafft, einen Nekrolord in die Gruft zu bekommen.\n\nIn seiner Nachricht bat Durkon um Unterstützung. Ihr werdet ihn suchen und ihm helfen, {name}. Die Gruft befindet sich an der westlichen Grenze des Dorfplatzes.", sourceObjective = "Sucht Dragoner Durkon bei der Gruft von Wintergarde in der Drachenöde auf.", completion = "Oh Junge, hier unten ist die Hölle los! Ich habe es beim letzten Mal kaum lebend herausgeschafft - weshalb ich dann die Bitte an den Hochkommandaten gestellt habe.\n\n<Durkon mustert Euch von oben bis unten.>\n\nIhr habt diesen irren Blick in Euren Augen, {race}. Glücklicherweise muss man irre sein, um das zu tun, was ich gleich von Euch verlangen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[12310] = { id = 12310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine prompte Reaktion", description = "Unsere Reaktion muss prompt erfolgen. Und entschlossen. Wir müssen diesen Wilden zeigen, dass sie sich besser nicht mit uns anlegen sollten.\n\nUnsere Späher haben die restlichen Fährtenleser von Silberwasser ausfindig gemacht… Ihr wisst schon, die, die nicht in den Flammen umgekommen sind. Anscheinend blockieren sie die Straße nach Südosten... vielleicht versuchen sie ja, uns einzukreisen.\n\nBegebt Euch zum Posten des Waldrandes und kümmert Euch um sie. Ihr Anführer ist angeblich ein Mann namens Vladek... stellt sicher, dass er auf der Strecke bleibt.", sourceObjective = "Leutnant Dumont möchte, dass Ihr zum Posten des Waldrands geht und Vladek sowie 7 Fährtenleser von Silberwasser erledigt.", progress = "Ist es vollbracht, {name}?", completion = "Was für eine Schande, dass sich diese Fährtenleser als… befallen herausgestellt haben. Wir hätten schon noch ein paar mehr Kämpfer gebrauchen können.\n\nMögen ihre armen Seelen in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12311] = { id = 12311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gruft des Adligen", description = "Innerhalb der kalten Steinmauern dieser Gruft liegen die Gebeine der Adligen und der Würdenträger Nordends. Im Herzen dessen sitzt jetzt ein Nekrolord und erweckt die Leichen als Diener der Geißel wieder.\n\nIhr müsst es bis zum Ende der Gruft schaffen und Nekrolord Amarion töten. Nur dann wird der Angriff aus dem Inneren der Gruft zum erliegen kommen!\n\nUnd, {name}, haltet Ausschau nach allen Informationen, die sich in dem Raum verbergen, in dem Amarion haust.", sourceObjective = "Dragoner Durkon in der Feste Wintergarde möchte, dass Ihr Nekrolord Amarion tötet.", completion = "Wenn wir es jetzt schaffen, die Angriffe der Geißel vom Äußeren der Feste zu stoppen, schaffen wir es vielleicht, Hilfe zu Lord Fordragon an der Pforte des Zorns zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[12312] = { id = 12312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Geißel", description = "Um die fleischgebundenen Kapitel dieses Folianten herum sind seltsame Symbole gekritzelt, sowie Formen, die mit einer Klinge in die Seiten gekratzt worden zu sein scheinen. Ihr habt keine Ahnung, was dort geschrieben steht, doch Ihr seid Euch sicher, dass, was auch immer es sein mag, es wichtig ist.\n\nÜbergebt den Folianten an Dragoner Durkon, welcher an der Oberseite der Gruft von Wintergarde Wache hält.", sourceObjective = "Bringt den fleischgebundenen Folianten zu Dragoner Durkon in der Feste Wintergarde in der Drachenöde.", progress = "Ein Foliant der Geißel?", completion = "Welche Informationen dieses Buch auch birgt, sie müssen von großer Bedeutung sein! Als Ihr auf der Flucht wart, konnte ich das Heulen und Klagen durch die Gruft hallen hören!\n\nDer Oberkommandant muss darüber in Kenntnis gesetzt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12313] = { id = 12313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet das Braufest!", description = "Rettet das Braufest! Sprecht mit dem Spion des Braufests im Grimmigen Säufer in den Schwarzfelstiefen.", sourceObjective = "Sprecht mit dem Spion des Braufests im Grimmigen Säufer in den Schwarzfelstiefen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12314] = { id = 12314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit Kapitänin Zorna!", description = "Die Streitkräfte der Horde sind kurz davor, unsere Reihen zu durchbrechen und die Eroberung der Venturebucht abzuschließen, wenn wir nicht handeln. Ihre Soldaten werden dabei von Kapitänin Zorna angeführt, in der Nähe des Schiffs an der abgelegenen Seite der Bucht.\n\nWenn Ihr sie besiegen könnt, bricht die Offensive der Horde zusammen und wir können den Hafen einnehmen. Seid auf der Hut, {name}, denn Zorna ist eine starke Kämpferin. Ihr werdet mehrere Leute brauchen, um sie zu besiegen, es sei denn, Ihr habt Zugang zu einem reparierten Schredder. Den könntet Ihr zu Eurem Vorteil einsetzen.", sourceObjective = "Tötet Kapitänin Zorna und erstattet Baron Freimann in der Venturebucht Bericht.", progress = "Habt Ihr Kapitänin Zorna erschlagen?", completion = "Gut gemacht, {name}! Ohne ihre Anführerin ist die Horde schwach und unorganisiert. Ich werde unsere Männer zum Angriff formieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12315] = { id = 12315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschmettert Kapitän Hellwasser!", description = "Mit jedem Vorrücken treffen unsere Männer auf frische Truppen der Allianz, so als ob ihr Kommandant jeden meiner Schritte vorausahnen würde!\n\nEs ist an der Zeit, dass für den guten Kapitän Hellwasser die letzte Stunde schlägt. Er befehligt seine Truppen von Bord eines Zerstörers der Allianz am anderen Ende der Bucht.\n\nDas wird kein einfacher Kampf, {name}! Zieht mit ein paar vertrauensvollen Freunden los oder schlitzt Hellwasser mit einem der reparierten Schredder auf, falls Ihr einen Schlüssel dafür besitzt! So oder so - er muss sterben!", sourceObjective = "Tötet Kapitän Hellwasser und erstattet anschließend General Khazgar in der Venturebucht Bericht.", completion = "Ihr seid ein wahrer Soldat der Horde, {name}! Euer Mut wird meine Männer zum Sieg führen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12316] = { id = 12316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet sie auf!", description = "Wir können nicht zulassen, dass die Horde die Venturebucht kontrolliert. Der Hafen ist für unsere Operationen in den Grizzlyhügeln und dahinter überlebenswichtig.\n\nHauptmann Starkmantel ist mit dem Rest der Westfallbrigade nach Osten aufgebrochen, um einen Weg durch die Berge zu finden, also haben wir keine Verstärkungen mehr.\n\nWerft Euch in die Schlacht, {name}, und tötet die Berserker aus Burg Siegeswall, welche die Horde gegen uns gesandt hat. Mäht sie nieder, bis keiner mehr steht. Die Allianz muss diesen Hafen einnehmen!", sourceObjective = "Besiegt 10 Einheiten oder Spieler der Horde in der Venturebucht und kehrt zu Leutnant Stuart zurück.", completion = "Eure Tapferkeit hat die Männer der Westfallbrigade inspiriert. Nun kämpfen sie mit noch größerer Entschlossenheit. Der Hafen wird bald unser sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12317] = { id = 12317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet sie auf!", description = "Diese vermaledeite Westfallbrigade stellt sich als härterer Gegner heraus, als wir gedacht haben. Obwohl sie nur wenige sind, kämpfen sie gut und tapfer, und wir können es uns nicht leisten, abzuwarten.\n\nDer Befehl Eroberin Krennas lautet, den Hafen schnell einzunehmen. Ihr müsst die Pattsituation aufheben, {name}. Findet die Marinesoldaten des Gegners und schlachtet sie ab, bis der Widerstand gebrochen ist. Erst dann können wir den Hafen einnehmen.\n\nBeeilt Euch. Wir wollen Eroberin Krenna nicht warten lassen.", sourceObjective = "Besiegt 10 Einheiten oder Spieler der Allianz in der Venturebucht und kehrt zu Zenturion Kaggrum zurück.", completion = "Der Hafen wird bald unser sein. Ihr habt uns heute einen großen Dienst erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12318] = { id = 12318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet das Braufest!", description = "{name}, unsere Spione haben ein teuflisches Komplott ans Licht gebracht! Die Dunkeleisenzwerge wollen unser geliebtes Braufest dem Erdboden gleichmachen!\n\nCoren Düsterbräu, Oberhaupt einer abtrünnigen Familie von Braumeistern, hat die Zwerge der Schwarzfelstiefen mobilisiert - zudem werden wir auch noch ständig von ihren Maulwurfmaschinen angegriffen.\n\nUnser Spion befindet sich im \"Grimmigen Säufer\", einer Taverne im Inneren des Schwarzfelsens. Er wird mehr über Düsterbräus Komplott wissen.", sourceObjective = "Sprecht mit dem Spion des Braufests im Grimmigen Säufer in den Schwarzfelstiefen.", completion = "Ihr kommt vom Braufestlager? Was für ein Tag! Das Braufest kann vielleicht noch gerettet werden.\n\n{name}, Coren Düsterbräu muss gestoppt werden! Wir dürfen nicht zulassen, dass er unseren heiligen Feiertag sabotiert. Das Bier muss fließen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12319] = { id = 12319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rätsel des Folianten", description = "Worum könnte es sich handeln, {name}? Es handelte sich bestimmt um keinen gewöhnlichen Fluch, den der verdammte Lich auf Euch gelegt hat!\n\n<Durkon blättert die entsetzlichen Seiten des Folianten durch.>\n\nIch weiß nicht einmal, ob ich es richtig herum halte. Wir müssen herausfinden, welche Informationen dieser Foliant birgt!\n\n<Durkon gibt Euch das Buch.>\n\nDer Oberkommandant wird wissen, was zu tun ist. Bringt ihm den fleischgebundenen Folianten und schildert ihm genau, was hier vorgefallen ist.", sourceObjective = "Übergebt Oberkommandant Halford Wyrmbann in der Feste Wintergarde in der Drachenöde den fleischgebundenen Foliant.", progress = "Der Nekrolord ist Geschichte?", completion = "<Halfords Augen öffnen sich weit.>\n\nDas Schicksal lächelt heute auf uns herab, {name}. Ich kenne genau den Richtigen, den man wegen dieses Folianten aufsuchen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[12320] = { id = 12320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sprache des Todes verstehen", description = "Nehmt das Buch und folgt dem Pfad zur Kaserne. Nehmt in der Kaserne die Treppe hinunter zum Gefängnis. Dort werdet Ihr Inquisitor Hallard und unseren Bürgermeister Gottfried finden. Ich glaube, dass Gottfried das fehlende Teil dieses Puzzles ist und das Hallard genau der richtige ist, um daraus ein vollständiges Bild zu machen.\n\nGeht!", sourceObjective = "Bringt den fleischgebundenen Folianten zu Inquisitor Hallard im Gefängnis der Feste Wintergarde.", progress = "Kommt Ihr vom Oberkommando, mein Sohn?", completion = "Mit der entsprechenden Motivation wird uns Gottfried vielleicht verraten, was er darüber weiß.\n\n<Hallard wendet sich Bürgermeister Gottfried zu.>\n\nNicht wahr, Bürgermeister?", sourceObjectiveStatus = "unverified-source-field" }
quests[12321] = { id = 12321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine rechtschaffene Predigt", description = "Gottfried Guters, einst ein rechtschaffener Mann und Bürgermeister von Wintergarde, arbeitet nun für die Geißel. Seine Verwandlung vom Menschen zu einem untoten Ghul kam langsam und mit der Zeit. Nun hört er den Ruf des Lichkönigs und lebt nur noch, um seinem Meister zu dienen.\n\nDoch wie alle Mitglieder der Geißel beherrscht Gottfried die Sprache des Todes und mit der richtigen Überredungskunst wird er uns erzählen, was wir über den Folianten wissen müssen.\n\nKehrt zum Oberkommandanten an die Front zurück, sobald Ihr gehört habt, was Ihr hören sollt. Ich werde hier dementsprechend aufräumen.", sourceObjective = "Wartet, bis Inquisitor Hallard seine rechtschaffene Predigt gehalten hat, und kehrt dann mit Euren Entdeckungen zu Oberkommandant Halford Wyrmbann in der Feste Wintergarde in der Drachenöde zurück.", completion = "Wir hätten über das verfluchte Mausoleum Bescheid wissen sollen. Das ist absurd! Herzog August Feindhammer und Ambo Unkesch werden zur Vorbereitung des nächsten Angriffs an die Front geschickt werden.\n\nSobald Ihr die Minen geräumt habt, werde ich Euch zu Feindhammer schicken, sodass wir mit unserem Angriff auf die Geißel von Naxxramas beginnen können!\n\nDie bisher von Euch gesammelten Informationen werden von unseren fähigsten Greifen zu Lord Fordragon an die Pforte des Zorns gebracht werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12323] = { id = 12323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuchert sie aus", description = "In einigen der Gebäuden hier in der Mitte der Venturebucht gibt es noch immer vereinzelte Gruppen von feigen Mitarbeitern der Venture Company. Ich brauche zwar jeden Mann, den ich entbehren kann, da draußen für den Kampf gegen die Horde, jedoch können wir genauso wenig zulassen, dass diese Nachzügler der Venture Company in diesen Gebäuden campieren.\n\nVielleicht können wir sie davon \"überzeugen\", auf ihr Schiff zurückzukehren. Nehmt diese Rauchbombe hier und räuchert mit ihr die Nachzügler in der Baracke, dem Sägewerk oder im Stall aus. Geht jedoch nicht zu nah ran - wahrscheinlich beißen sie.", sourceObjective = "Jagt mithilfe der Rauchbombe 20 Nachzügler der Venture Co. aus ihren Gebäuden und meldet Euch anschließend bei Unteroffizier Downey.", progress = "Habt Ihr schon den letzten Rest der Männer von der Venture Company ausgeräuchert?", completion = "Gut gemacht, Soldat! Nun kann sich der Rest der Männer auf die Horde konzentrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12324] = { id = 12324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuchert sie aus", description = "Es ist ja nicht nur so, dass dieser Hafen lediglich mit feigen Allianzheulsusen verpestet wäre, nein, denn um die Sache noch schlimmer zu machen, gibt es noch immer Mitarbeiter der Venture Company, die sich in einigen Gebäuden verkrochen haben. Es ist einfach reine Zeitverschwendung, sie zu töten, und ich kann sowieso keine Krieger entbehren.\n\nVielleicht können wir sie davon \"überzeugen\", auf ihr Schiff zurückzukehren. Nehmt diese Rauchbombe hier und räuchert mit ihr die Nachzügler in der Baracke, dem Sägewerk oder im Stall aus. Geht jedoch nicht zu nah an sie ran - man kann nie wissen, welche Krankheiten sie in sich tragen.", sourceObjective = "Jagt mithilfe der Rauchbombe 20 Nachzügler der Venture Co. aus ihren Gebäuden und meldet Euch anschließend bei Steingardist Rachtotem.", completion = "Der General wird sehr darüber erfreut sein, dass Ihr Euch um die Venture Company gekümmert habt. Nun können sich die Männer darauf konzentrieren, die Allianz zurückzuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12325] = { id = 12325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinein ins Feindgebiet", description = "Ihr habt viel zu unserem Kampf gegen die Geißel beigetragen, {name}. Tatsächlich steigt die Moral derjenigen, die mit Euch in Berührung gekommen sind, rasant an! Solch einen Einfluss habt Ihr auf die Soldaten und Bewohner von Wintergarde, <Verbündeter/Verbündete>.\n\nUnd es ist Euch zu verdanken, dass wir nun darauf vorbereitet sind, in die Offensive zu gehen! Ihr sollt Euch bei Herzog August Feindhammer melden. Er befindet sich auf der anderen Seite der Aasfelder bei Thorsons Posten, östlich von hier. Greifenkommandant Urik an der Greifenstation hat einen speziellen Greifen bereitgestellt, der Euch hinter Feindeslinien absetzen wird. Geht jetzt!", sourceObjective = "Sprecht mit Greifenmeister Urik und fliegt zu Thorsons Posten. Meldet Euch bei Herzog August Feindhammer, wenn Ihr bei Thorsons Posten in der Drachenöde angekommen seid.", completion = "Ah, der namhafte Held ist angekommen. Willkommen im Zentrum des Geschehens, {name}. Erlaubt mir, Euch auf den neuesten Stand zu bringen!\n\nThel'zans stärkste Truppen haben sich bis ins Mausoleum von Wintergarde durchgekämpft. Sie erkunden seine Tiefen auf der Suche nach Leichen und Seelen, um sie auf Wintergarde zu hetzen, während Naxxramas schreckliche Seuchenmaschinen der Geißel auf uns niederprasseln lässt, um uns in Schach zu halten!\n\nWir müssen jetzt zuschlagen und darauf hoffen, dass Lord Fordragon bei den Zornpforten noch etwas länger durchhalten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12326] = { id = 12326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dampfpanzerüberraschung", description = "Diese Mission dreht sich nur um eins: Suchen und Vernichten. Ihr werdet mit einem Panzer in die Aasfelder fahren und die Seuchewagen in ihre Einzelteile zerlegen. Der Panzer wird von drei Soldaten der 7. Legion begleitet, die alle überleben müssen, wenn die Mission erfolgreich enden soll!\n\nIhr werdet nah an einen Seuchewagen heranfahren müssen, um Euren Ingenieur einzusetzen. Sobald es keine Seuchewagen auf dem Feld mehr gibt, bewegt Euch in Richtung des Mausoleums, das sich vor der zerstörten Festung befindet, und setzt den Rest Eures Trupps ab. Trefft Euch im Inneren des Mausoleums mit Ambo Unkesch.", sourceObjective = "Zerstört mithilfe des Dampfpanzers der Allianz 6 Seuchewagen und ladet die Elitesoldaten der 7. Legion beim Mausoleum von Wintergarde ab. Sprecht anschließend mit Ambo Unkesch im Inneren des Mausoleums von Wintergarde, wenn Eure Aufgabe erledigt ist.", progress = "Man nennt mich Unkesch - Ambo Unkesch. Und das Vergnügen ist ganz auf deiner Seite.", completion = "Wieso ich keine Hosen trage, ist nicht wichtig. Sagen wir einfach mal, dass mich ein Schrapnell der Geißel am falschen Ort getroffen hat und belassen es dabei, in Ordnung?\n\nDu hast also die Seuchewagen auf den Feldern alle gemacht und meine Soldaten in einem Stück hier abgeliefert. Beeindruckend. Du bist einer der Ersten, der's bis hierher geschafft hat, Kumpel. Schade nur, dass du gleich wieder raus auf die Aasfelder musst. Ja, genau - wir hatten so was wie 'nen kleinen Rückschlag.", sourceObjectiveStatus = "unverified-source-field" }
quests[12327] = { id = 12327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außerkörperliche Erfahrung", description = "Ah, Ihr sucht nach einer Vision der Vergangenheit. Ihr seid <ein weiser/eine weise:r> {race}.\n\nJedes Mal, wenn jemand hierher kommt und etwas wissen möchte, dann wollen sie anscheinend immer nur die Zukunft erfahren. Wenn Ihr mein Alter erreicht, dann erkennt Ihr, dass es in den meisten Fällen einfach nützlicher ist, in die Vergangenheit zu blicken.\n\nTrinkt von diesem Trank und werft einen Blick in meine Kristallkugel. Lasst uns sehen, was wir herausbekommen können.", sourceObjective = "Trinkt den samtigen Trank bei Ruunas Kristallkugel und werdet Zeuge einer Vision der Vergangenheit.", progress = "Ja, {name}?", completion = "Habt Ihr irgendetwas aus Eurer Vision erfahren können? Ihr habt Julheim erwähnt, während Ihr Euch in Trance befandet - was das zweite Mal ist, dass heute jemand den Namen dieses Ortes ausspricht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12328] = { id = 12328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruunas Bitte", description = "Ich werde Euch für meine Dienste kein Gold abnehmen, weil ich ahne, dass Eure Taten notwendig sind und viel davon abhängt, was Ihr heute lernt.\n\nIch werde Euch jedoch darum bitten, ein Reagenz für mich zu besorgen. Bringt mir samtigen Staub von den Farnfressermotten nordöstlich von hier. Tut das und ich werde Euch einen Trank bereiten, der Euch an den Ort und die Zeit bringt, da die Geschehnisse stattfanden, die Ihr gesehen haben müsst.", sourceObjective = "Ruuna die Blinde möchte, dass Ihr 4 Handvoll samtigen Staubs besorgt.", progress = "Habt Ihr den Staub bekommen, {name}?", completion = "Gut. Das wird ausreichen.\n\nIm Handumdrehen werde ich den Trank fertig haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12329] = { id = 12329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal und Zufall", description = "Es gibt zwei Arten von Leuten auf dieser Welt, {name}. Diejenigen, die an den Zufall glauben, und diejenigen, die nicht daran glauben.\n\nAn dem Tag, als ich mein Augenlicht verlor, wurde mir das Geschenk des Hellsehens zuteil. Ich nehme an, dass Ihr erraten könnt, zu welcher Gruppe von Leuten ich gehöre.\n\nHeute früh wurde einer jungen Frau namens Sasha dieselbe Vision gewährt wie Euch. Ihr werdet mit ihr sprechen wollen.\n\nIhr findet sie direkt östlich von hier im Handelsposten Weißkiefer auf dem Weg nach Julheim.", sourceObjective = "Sprecht mit Sasha im Handelsposten Weißkiefer.", completion = "Ich habe mich schon gefragt, wann Ihr auftauchen würdet. Denkt Ihr, dass Ihr mir hier helfen könntet?", sourceObjectiveStatus = "unverified-source-field" }
quests[12330] = { id = 12330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anatol wird reden", description = "Meine Schwester ist hier irgendwo, und ich kriege dieses Monster einfach nicht zum Reden.\n\nEr kümmert sich anscheinend nicht um sein eigenes Wohlergehen, aber ich habe da eine Idee. Ich kenne Anatols Frau, Tatjana, noch aus der Zeit, bevor der Wolfkult ankam; sie war eine Pferdehändlerin.\n\nNehmt diesen Betäubungspfeil. Bringt sie lebend zurück, wir werden sie brauchen, wenn wir ein Druckmittel gegen Anatol haben wollen.\n\nIch werde Euch helfen, die Person, die hinter all dem steckt zu finden, sobald wir meine Schwester haben.", sourceObjective = "Sasha im Handelsposten Weißkiefer möchte, dass Ihr den Betäubungspfeil nehmt und ihn auf Tatjana in Julheim schießt. Bringt Tatjana dann zum Handelsposten Weißkiefer zurück.", completion = "Das… das war knapp.\n\nWir müssen Anya retten. Jetzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12331] = { id = 12331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
